<template>
  <span
    class="region-pill"
    :class="cls"
    :data-test="'region-pill-' + (region || 'unknown')"
  >{{ label }}<span v-if="icon">{{ icon }}</span></span>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import type { InfraRegion, InfraSeverity } from './infrastructure-topology.types';

/**
 * Region badge shared across the infrastructure diagram.
 * Severity → colour rules: severity 'error' always wins (red), then aligned =
 * green ✓, advisory cross-region = amber ⓘ, critical mismatch = red ⚠,
 * unknown / n/a (shared) = neutral grey (no warning).
 */
export default defineComponent({
  name: 'RegionPill',
  props: {
    region: { type: String as () => InfraRegion, default: null },
    matches: { type: Boolean as () => boolean | null, default: null },
    severity: { type: String as () => InfraSeverity, default: null },
  },
  computed: {
    label(): string {
      return this.region && this.region !== 'shared'
        ? this.region.toUpperCase()
        : 'SHARED';
    },
    cls(): string {
      if (this.severity === 'error') return 'region-pill--bad';
      if (this.matches === true) return 'region-pill--ok';
      if (this.severity === 'advisory') return 'region-pill--advisory';
      if (this.matches === false) return 'region-pill--bad';
      return 'region-pill--unknown';
    },
    icon(): string {
      if (this.severity === 'error') return ' ⚠';
      if (this.matches === true) return ' ✓';
      if (this.severity === 'advisory') return ' ⓘ';
      if (this.matches === false) return ' ⚠';
      return '';
    },
  },
});
</script>

<style scoped lang="scss">
.region-pill {
  font-size: 11px;
  font-weight: 700;
  padding: 1px 7px;
  border-radius: 9999px;
  white-space: nowrap;
  line-height: 1.5;
}
.region-pill--ok {
  background: rgb(220 252 231);
  color: rgb(21 128 61);
}
.region-pill--advisory {
  background: rgb(254 243 199);
  color: rgb(180 83 9);
}
.region-pill--bad {
  background: rgb(254 226 226);
  color: rgb(185 28 28);
}
.region-pill--unknown {
  background: rgb(241 245 249);
  color: rgb(100 116 139);
}
</style>
