<template>
  <div class="page-container page-height-limit" data-test="infrastructure-page">
    <div class="settings-page-content">
      <div class="settings-page-header">
        <h2 class="settings-page-title">{{ $t('infrastructure') }}</h2>
        <p class="settings-page-subtitle">{{ $t('infrastructure_desc') }}</p>
      </div>

      <q-tabs
        v-model="activeTab"
        dense
        no-caps
        align="left"
        class="text-primary"
        active-color="primary"
        indicator-color="primary"
        data-test="infrastructure-tabs"
      >
        <q-tab
          name="topology"
          :label="$t('infra_tab_topology')"
          data-test="infra-tab-topology"
        />
        <q-tab
          name="processing"
          :label="$t('infra_tab_processing')"
          data-test="infra-tab-processing"
        />
        <q-tab
          name="scheduled"
          :label="$t('infra_tab_scheduled')"
          data-test="infra-tab-scheduled"
        />
      </q-tabs>
      <q-separator />

      <q-tab-panels v-model="activeTab" animated class="bg-transparent">
        <q-tab-panel name="topology" class="q-pa-none q-pt-md">
          <div
            v-if="loading"
            class="flex flex-center q-pa-xl"
            data-test="infrastructure-loading"
          >
            <q-spinner-dots color="primary" size="40px" />
          </div>

          <q-banner
            v-else-if="error"
            class="bg-red-1 text-red-9"
            data-test="infrastructure-error"
          >
            {{ $t('infrastructure_load_failed') }}
            <template #action>
              <q-btn flat :label="$t('retry')" data-test="infrastructure-retry" @click="load" />
            </template>
          </q-banner>

          <!-- load() forces error=true whenever topology ends up null/empty, so
               the three states (loading / error+retry / diagram) are exhaustive. -->
          <InfrastructureDiagram
            v-else
            :topology="topology"
            :moduleStatus="moduleStatus"
            :processModules="processModules"
            streamStatus="live"
            data-test="infrastructure-diagram-host"
            @activate-module="goToModuleSettings"
          />
        </q-tab-panel>

        <q-tab-panel name="processing" class="q-pa-none q-pt-md">
          <ProcessingTasksStatus />
        </q-tab-panel>

        <q-tab-panel name="scheduled" class="q-pa-none q-pt-md">
          <ScheduledTasksStatus />
        </q-tab-panel>
      </q-tab-panels>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import InfrastructureDiagram from 'src/components/Infrastructure/InfrastructureDiagram.vue';
import ProcessingTasksStatus from 'src/pages/Settings/Components/Infrastructure/ProcessingTasksStatus.vue';
import ScheduledTasksStatus from 'src/pages/Settings/Components/Infrastructure/ScheduledTasksStatus.vue';
import InfrastructureApiService from 'src/services/infrastructure/InfrastructureApiService';
import DocTypeApiService from 'src/services/settings/DocTypeApiService';
import type { InfrastructureTopology } from 'src/components/Infrastructure/infrastructure-topology.types';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { toBoolPreference } from 'src/utils/preferenceBool';
import logger from 'src/utils/logger';

// Optional modules a customer can switch on/off, mapped to their org-preference
// key. Diagram component key → setting key. Only these get an activated/
// deactivated badge; everything else is an always-on part of the platform.
// The values are the canonical preference keys (mirrored from src/constants:
// open_search_enabled / workflow_builder_setting / auto_accounting_setting /
// docnet_setting) — inlined as plain string literals so this page does not pull
// the heavy src/constants barrel (and its i18n boot chain) into its chunk.
const MODULE_SETTING_KEYS: Record<string, string> = {
  fulltext: 'OPENSEARCH_ENABLED',
  docflow: 'WORKFLOW_BUILDER_MODULE_SETTING',
  autoacc: 'AUTO_ACCOUNTING_ACTIVATE_SETTING',
  docnet: 'DOCNET_SETTING',
};

// PO Matching is NOT an org preference — since the 2023 preference migration
// it is gated per document type via the PO_IS_ACTIVE attribute. The org "has"
// PO matching when ANY doc type has it switched on. Canonical constant:
// CONSTANTS.is_po_active (src/constants.ts) — inlined for the same chunk
// reason as MODULE_SETTING_KEYS above.
const PO_IS_ACTIVE_KEY = 'PO_IS_ACTIVE';

export default defineComponent({
  name: 'InfrastructurePage',
  components: { InfrastructureDiagram, ProcessingTasksStatus, ScheduledTasksStatus },
  setup() {
    const settingStore = useSettingStore();
    const { user_settings } = storeToRefs(settingStore);
    return { user_settings };
  },
  data() {
    return {
      activeTab: 'topology' as 'topology' | 'processing' | 'scheduled',
      topology: null as InfrastructureTopology | null,
      loading: true,
      error: false,
      api: new InfrastructureApiService(),
      docTypeApi: new DocTypeApiService(),
      // null = unknown (fetch pending/failed) → the pipeline treats the stage
      // as enabled, never flashing a false "Inactive".
      poMatchActive: null as boolean | null,
    };
  },
  computed: {
    moduleStatus(): Record<string, boolean> {
      // Until settings have loaded, expose nothing — an empty map renders no
      // module badges, avoiding a false "deactivated" flash before the async
      // settings fetch resolves (see settings race-condition note).
      const settings = this.user_settings || {};
      if (Object.keys(settings).length === 0) return {};
      const status: Record<string, boolean> = {};
      for (const [componentKey, settingKey] of Object.entries(MODULE_SETTING_KEYS)) {
        status[componentKey] = toBoolPreference(settings[settingKey]);
      }
      return status;
    },
    // Optional-module map for the process pipeline. A key is only present once
    // its status is actually KNOWN — the pipeline treats missing keys as
    // enabled (same race guard as moduleStatus above).
    processModules(): Record<string, boolean> {
      const out: Record<string, boolean> = {};
      if (this.poMatchActive !== null) out.pomatch = this.poMatchActive;
      if (Object.prototype.hasOwnProperty.call(this.moduleStatus, 'autoacc')) {
        out.autoacc = this.moduleStatus.autoacc;
      }
      return out;
    },
  },
  mounted() {
    this.load();
    // Fire-and-forget in parallel — a PO-attribute failure must never affect
    // the topology loading/error states.
    this.loadPoMatchStatus();
  },
  methods: {
    goToModuleSettings(moduleKey: string) {
      // Each optional module is switched on its own Modules sub-page. PO
      // matching is the exception — it has no Modules toggle and is enabled per
      // document type via the PO_IS_ACTIVE attribute, so it routes to Document
      // Types. Unknown keys fall back to the Modules landing page.
      const MODULE_ROUTE: Record<string, string> = {
        fulltext: '/settings/modules/dashboards-analytics',
        docflow: '/settings/modules/document-integration',
        docnet: '/settings/modules/document-integration',
        autoacc: '/settings/modules/order-finance',
        pomatch: '/settings/document-types',
      };
      this.$router.push(MODULE_ROUTE[moduleKey] ?? '/settings/modules');
    },
    async loadPoMatchStatus() {
      try {
        const res = await this.docTypeApi.getAllDocumentTypeAttributes(PO_IS_ACTIVE_KEY);
        // Response shape: { success, data: { docTypeKey: [{ attribute_key,
        // attribute_value, ... }] } } (see store/Document/attributes.store.ts).
        if (!res || res.success === false || !res.data) return;
        this.poMatchActive = Object.values(
          res.data as Record<string, Array<{ attribute_key: string; attribute_value: string }>>,
        ).some(
          (attrs) =>
            Array.isArray(attrs) &&
            attrs.some(
              (a) => a.attribute_key === PO_IS_ACTIVE_KEY && a.attribute_value === 'true',
            ),
        );
      } catch (err) {
        logger.warn('[Infrastructure] PO attribute load failed', err);
      }
    },
    async load() {
      this.loading = true;
      this.error = false;
      try {
        const result = await this.api.getTopology();
        // Treat a 200 with an empty/malformed body as a failure rather than
        // rendering an empty diagram. Count ACTUAL components — groups:[] and
        // groups:[{components:[]}] both have zero components → error/retry.
        const totalComponents =
          result && Array.isArray(result.groups)
            ? result.groups.reduce(
                (n, g) => n + (Array.isArray(g.components) ? g.components.length : 0),
                0,
              )
            : 0;
        this.topology = totalComponents > 0 ? result : null;
        if (!this.topology) this.error = true;
      } catch (err) {
        this.error = true;
        logger.warn('[Infrastructure] topology load failed', err);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>

