/**
 * Pure, framework-free helpers for the Infrastructure task-status tables.
 *
 * Extracted from ProcessingTasksStatus.vue / ScheduledTasksStatus.vue so the
 * label mapping and traffic-light logic are unit-testable without mounting
 * Quasar / DocBitsTable, and shared by both components (single source of truth).
 */

// ---------------------------------------------------------------------------
// Processing tasks (document-processing steps)
// ---------------------------------------------------------------------------

// Curated, language-NEUTRAL display names for the processing task types. These
// are product/feature proper nouns (OCR, Barcode, PO Match …) — kept out of
// Tolgee on purpose so the translation sync can never mangle them. Identical in
// every locale. Keep in sync with the service whitelist in doc2-api
// task_manager.py (processing_task_status endpoint).
export const PROCESSING_LABELS: Record<string, string> = {
  'celery.core.process': 'Document Processing',
  'celery.ocr.pdf_searchable': 'OCR',
  'celery.tr_ocr.process_trocr_request': 'TR-OCR',
  'celery.barcode.barcode_split': 'Barcode Split',
  'celery.barcode.barcode_extraction': 'Barcode Extraction',
  'celery.extraction.extraction': 'Extraction',
  'celery.po_match.po_match': 'PO Match',
};

export function labelForService(service: string): string {
  if (PROCESSING_LABELS[service]) return PROCESSING_LABELS[service];
  // Fallback for an unknown service: last dotted segment, snake_case → Title.
  const last = (service || '').split('.').pop() || service || '';
  return last
    .replace(/_/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .trim();
}

export type ProcessingBadgeState = 'error' | 'active' | 'ok';

export interface ProcessingBadge {
  state: ProcessingBadgeState;
  count: number; // 0 for the 'ok' badge
  color: string; // Quasar colour token
}

/**
 * Traffic light for one processing step. errors and "in progress" are
 * INDEPENDENT signals — both badges show when both apply, so a customer sees a
 * failure even while work is still running. Only when both are zero is it OK.
 */
export function processingBadges(row: {
  errors_recent: number;
  pending: number;
}): ProcessingBadge[] {
  const badges: ProcessingBadge[] = [];
  if (row.errors_recent > 0) {
    badges.push({ state: 'error', count: row.errors_recent, color: 'negative' });
  }
  if (row.pending > 0) {
    badges.push({ state: 'active', count: row.pending, color: 'warning' });
  }
  if (row.errors_recent === 0 && row.pending === 0) {
    badges.push({ state: 'ok', count: 0, color: 'positive' });
  }
  return badges;
}

// ---------------------------------------------------------------------------
// Scheduled tasks (Celery beat)
// ---------------------------------------------------------------------------

// snake_case / dotted task identifier → human "Title Case" (no curated mapping;
// beat task names are technical but readable once spaced out).
export function prettifyTaskName(raw: string): string {
  return (raw || '')
    .replace(/[._]/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .trim();
}

export type ScheduledStatusKey = 'on_schedule' | 'delayed' | 'unknown';

// Maps the backend's Status string to a stable i18n-key suffix
// (infra_task_status_<key>) — decouples the UI label from the wire value.
export function scheduledStatusKey(status: string): ScheduledStatusKey {
  if (status === 'On Schedule') return 'on_schedule';
  if (status === 'Delayed') return 'delayed';
  return 'unknown';
}

export function scheduledStatusColor(status: string): string {
  if (status === 'On Schedule') return 'positive';
  if (status === 'Delayed') return 'negative';
  return 'grey-5';
}
