<template>
  <div class="bg-tasks" data-test="scheduled-tasks">
    <div class="bt-toolbar">
      <span class="bt-hint" data-test="scheduled-tasks-hint">
        {{ $t('infra_sched_hint') }}
      </span>
      <q-btn
        outline
        dense
        no-caps
        color="primary"
        icon="mdi-refresh"
        :label="$t('infra_tasks_refresh')"
        :loading="loading"
        data-test="scheduled-tasks-refresh"
        @click="load"
      />
    </div>

    <div
      v-if="loading"
      class="flex flex-center q-pa-xl"
      data-test="scheduled-tasks-loading"
    >
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <q-banner
      v-else-if="error"
      class="bg-red-1 text-red-9"
      data-test="scheduled-tasks-error"
    >
      {{ $t('infra_tasks_load_failed') }}
      <template #action>
        <q-btn
          flat
          :label="$t('retry')"
          data-test="scheduled-tasks-retry"
          @click="load"
        />
      </template>
    </q-banner>

    <DocBitsTable
      v-else
      :rows="rows"
      :columns="cols"
      row-key="raw_name"
      table-id="scheduled_tasks_table"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: false,
        pagination: false,
        columnReorder: false,
      }"
      no-data-label="no_record_found"
      flat-style
      data-test="scheduled-tasks-table"
    >
      <template #body-cell-name="{ row }">
        <span :data-test="'scheduled-name-' + row.raw_name">{{ row.name }}</span>
      </template>

      <template #body-cell-last_run="{ row }">
        <span
          v-if="!row.last_run || row.last_run === 'Never'"
          class="bt-never"
          :data-test="'scheduled-lastrun-' + row.raw_name"
        >
          {{ $t('infra_task_never_run') }}
        </span>
        <span v-else :data-test="'scheduled-lastrun-' + row.raw_name">
          {{ relativeTime(row.last_run) }}
          <q-tooltip>{{ absoluteTime(row.last_run) }}</q-tooltip>
        </span>
      </template>

      <template #body-cell-status="{ row }">
        <q-badge
          :color="statusColor(row.status)"
          text-color="white"
          rounded
          :label="statusLabel(row.status)"
          :data-test="'scheduled-status-' + row.raw_name"
        />
      </template>
    </DocBitsTable>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { format, parseISO } from 'date-fns';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';
import InfrastructureApiService from 'src/services/infrastructure/InfrastructureApiService';
import type { BeatTaskStatus } from 'src/services/infrastructure/InfrastructureApiService';
import { useFormattedTimeAgo } from 'src/boot/timeago';
import logger from 'src/utils/logger';
import {
  prettifyTaskName,
  scheduledStatusColor,
  scheduledStatusKey,
} from './task-status-helpers';

interface TaskRow {
  raw_name: string;
  name: string;
  last_run: string;
  status: string;
}

export default defineComponent({
  name: 'ScheduledTasksStatus',
  components: { DocBitsTable },
  data() {
    return {
      rows: [] as TaskRow[],
      loading: true,
      error: false,
      api: new InfrastructureApiService(),
    };
  },
  computed: {
    cols(): UnifiedTableColumn[] {
      // sorting disabled (features.sorting:false): short list, simple snapshot.
      return [
        { name: 'name', label: this.$t('infra_task_name_col'), align: 'left', field: 'name' },
        { name: 'last_run', label: this.$t('infra_task_last_run_col'), align: 'left', field: 'last_run' },
        { name: 'status', label: this.$t('infra_task_status_col'), align: 'left', field: 'status' },
      ];
    },
  },
  mounted() {
    this.load();
  },
  methods: {
    relativeTime(value: string): string {
      return useFormattedTimeAgo(value);
    },
    absoluteTime(value: string): string {
      try {
        return format(parseISO(value), 'dd.MM.yyyy HH:mm:ss');
      } catch {
        return value;
      }
    },
    statusColor(status: string): string {
      return scheduledStatusColor(status);
    },
    statusLabel(status: string): string {
      // scheduledStatusKey → stable i18n suffix (on_schedule/delayed/unknown).
      return this.$t('infra_task_status_' + scheduledStatusKey(status));
    },
    async load() {
      this.loading = true;
      this.error = false;
      try {
        const res = await this.api.getBeatStatus();
        // ROLLOUT SHIM (remove once doc2-api PR #9644 is on every env): the old
        // /celery_log/celery_beat_status returned json.dumps(...) → a JSON
        // *string*. The fix returns a real array. Parse defensively until the
        // backend fix is everywhere, then drop the typeof-string branch.
        const tasks: BeatTaskStatus[] =
          typeof res === 'string' ? JSON.parse(res) : res;
        this.rows = (Array.isArray(tasks) ? tasks : []).map((t) => ({
          raw_name: t['Task Name'] || '',
          name: prettifyTaskName(t['Task Name'] || ''),
          last_run: t['Last Run Time'],
          status: t['Status'],
        }));
      } catch (err) {
        this.error = true;
        logger.warn('[ScheduledTasks] beat status load failed', err);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>

