<template>
  <div class="flow" data-test="process-flow-diagram">
    <!-- Toolbar: step caption + play/pause. data-test names kept from the old
         process mode so existing Playwright locators stay valid. -->
    <div class="flow-toolbar">
      <span class="flow-step-caption" data-test="infra-step-caption">{{
        currentCaption
      }}</span>
      <span class="flow-spacer"></span>
      <q-btn
        flat
        dense
        round
        :icon="playing ? 'mdi:pause' : 'mdi:play'"
        data-test="infra-play-toggle"
        @click="togglePlay"
      />
    </div>

    <div class="flow-canvas" data-test="process-canvas">
      <svg
        :viewBox="viewBox"
        :width="svgWidth"
        :height="H"
        class="flow-svg"
        preserveAspectRatio="xMinYMin meet"
      >
        <defs>
          <!-- Own marker id — SVG ids are document-global, so we must not
               collide with the architecture diagram's #infra-arrow. -->
          <marker
            id="process-arrow"
            markerWidth="9"
            markerHeight="9"
            refX="7"
            refY="3"
            orient="auto"
            markerUnits="strokeWidth"
          >
            <path d="M0,0 L7,3 L0,6 Z" class="flow-arrow-head" />
          </marker>
        </defs>

        <!-- Converging connectors from the three entry sources -->
        <path
          v-for="(entry, i) in entryNodes"
          :key="'entry-edge-' + entry.id"
          :d="entryPath(Number(i))"
          class="flow-link"
          :class="{
            'flow-link--flow': isEntryEdgeActive(entry.id),
            'flow-link--done': isEntryEdgeDone(entry.id),
          }"
          fill="none"
          marker-end="url(#process-arrow)"
          :data-test="'process-entry-edge-' + entry.id"
        />

        <!-- Linear connectors between stages -->
        <path
          v-for="i in stageNodes.length - 1"
          :key="'edge-' + (i - 1)"
          :d="stagePath(i - 1)"
          class="flow-link"
          :class="{
            'flow-link--flow': isEdgeActive(i - 1),
            'flow-link--done': isEdgeDone(i - 1),
          }"
          fill="none"
          marker-end="url(#process-arrow)"
          :data-test="
            'process-edge-' + stageNodes[i - 1].id + '-' + stageNodes[i].id
          "
        />

        <!-- Dashed stubs from every stage down to the datastore bar -->
        <line
          v-for="node in stageNodes"
          :key="'stub-' + node.id"
          :x1="node.cx"
          :y1="node.y + node.h"
          :x2="node.cx"
          :y2="barY"
          class="flow-store-stub"
          :data-test="'process-store-stub-' + node.id"
        />

        <!-- Entry source cards -->
        <foreignObject
          v-for="entry in entryNodes"
          :key="entry.id"
          :x="entry.x"
          :y="entry.y"
          :width="entry.w"
          :height="entry.h"
        >
          <div
            class="flow-box flow-box--entry"
            :class="{ 'flow-box--active': isEntryActive(entry.id) }"
            :data-test="'process-entry-' + entry.id"
          >
            <Icon :icon="entry.icon" class="flow-box-icon" />
            <span class="flow-box-label">{{ $t(entry.labelKey) }}</span>
          </div>
        </foreignObject>

        <!-- Pipeline stage cards -->
        <foreignObject
          v-for="node in stageNodes"
          :key="node.id"
          :x="node.x"
          :y="node.y"
          :width="node.w"
          :height="node.h"
        >
          <div
            class="flow-box flow-box--stage"
            :class="{
              'flow-box--active': isStageActive(node.id),
              'flow-stage--disabled': !node.enabled,
            }"
            :data-test="'process-stage-' + node.id"
          >
            <div class="flow-box-head">
              <Icon :icon="node.icon" class="flow-box-icon" />
              <span class="flow-box-label">{{ $t(node.labelKey) }}</span>
            </div>
            <div v-if="node.moduleKey" class="flow-box-module">
              <span
                class="flow-module-status"
                :class="
                  node.enabled
                    ? 'flow-module-status--on'
                    : 'flow-module-status--off'
                "
                :data-test="'process-stage-status-' + node.id"
                >{{ node.enabled ? $t('active') : $t('inactive') }}</span
              >
              <button
                v-if="!node.enabled"
                type="button"
                class="flow-module-activate"
                :data-test="'process-stage-activate-' + node.id"
                @click="$emit('activate-module', node.moduleKey)"
              >
                {{ $t('activate') }}
              </button>
            </div>
          </div>
        </foreignObject>

        <!-- Datastore bar: every service persists through these stores -->
        <foreignObject :x="barX" :y="barY" :width="barW" :height="STORE_H">
          <div class="flow-stores" data-test="process-datastores">
            <span class="flow-stores-label">{{
              $t('infra_flow_stage_datastores')
            }}</span>
            <span
              v-for="store in datastores"
              :key="store.id"
              class="flow-store-chip"
            >
              <Icon :icon="store.icon" class="flow-box-icon" />
              {{ $t(store.labelKey) }}
            </span>
          </div>
        </foreignObject>

        <!-- The travelling document -->
        <g
          class="flow-doc"
          :class="{ 'flow-doc--teleport': activeStep === 0 }"
          :style="{ transform: docTransform }"
          data-test="process-doc"
        >
          <circle r="15" class="flow-doc-circle" />
          <foreignObject x="-9" y="-9" width="18" height="18">
            <Icon icon="mdi:file-document-outline" class="flow-doc-icon" />
          </foreignObject>
        </g>
      </svg>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import { Icon } from '@iconify/vue';
import {
  PROCESS_ENTRY_SOURCES,
  PROCESS_STAGES,
  PROCESS_DATASTORES,
  isStageEnabled,
  type ProcessEntrySource,
  type ProcessStage,
} from './process-flow';

interface EntryNode extends ProcessEntrySource {
  x: number;
  y: number;
  w: number;
  h: number;
  cx: number;
  cy: number;
}

interface StageNode extends ProcessStage {
  enabled: boolean;
  x: number;
  y: number;
  w: number;
  h: number;
  cx: number;
  cy: number;
}

const ENTRY_W = 150;
const ENTRY_H = 60;
const ENTRY_GAP = 20;
const STAGE_W = 160;
const STAGE_H = 84;
const STAGE_GAP = 64;
const LEFT_PAD = 24;
const RIGHT_PAD = 40;
const TOP_PAD = 26;
const CONVERGE_GAP = 80; // space between the entry column and the first stage
const STORE_H = 56;
const STORE_GAP = 70; // vertical space between the pipeline and the datastore bar

const STEP_MS = 1400; // must stay > the 0.6s travel transition

export default defineComponent({
  name: 'ProcessFlowDiagram',
  components: { Icon },
  props: {
    // Optional-module activation per moduleKey (pomatch/autoacc). A MISSING
    // key means "unknown" (settings still loading) and counts as enabled —
    // the pipeline must never flash a deactivated stage. Only an explicit
    // false grays the stage out and makes the animation skip it.
    processModules: {
      type: Object as PropType<Record<string, boolean>>,
      default: () => ({}),
    },
  },
  emits: ['activate-module'],
  data() {
    return {
      // 0 = document sits at the entry source; 1..n = at activeStages[step-1]
      activeStep: 0,
      playing: true,
      timer: null as ReturnType<typeof setInterval> | null,
      // Completed loops — rotates the entry source (email → ftp → web)
      loopCount: 0,
      STORE_H,
    };
  },
  computed: {
    datastores() {
      return PROCESS_DATASTORES;
    },
    activeStages(): ProcessStage[] {
      return PROCESS_STAGES.filter((s) =>
        isStageEnabled(s, this.processModules),
      );
    },
    stepCount(): number {
      return this.activeStages.length + 1;
    },
    entrySource(): ProcessEntrySource {
      return PROCESS_ENTRY_SOURCES[
        this.loopCount % PROCESS_ENTRY_SOURCES.length
      ];
    },
    currentStage(): ProcessStage | null {
      return this.activeStep === 0
        ? null
        : (this.activeStages[this.activeStep - 1] ?? null);
    },
    currentCaption(): string {
      const key = this.currentStage
        ? this.currentStage.captionKey
        : this.entrySource.captionKey;
      return this.$t(key);
    },
    /**
     * Index of the document's stage in the FULL stage list (-1 = at entry).
     * Drives edge done/flow classes across skipped (disabled) stages: when the
     * doc jumps extraction → export, the skipped edges flip straight to done.
     */
    docFullIndex(): number {
      const stage = this.currentStage;
      return stage ? PROCESS_STAGES.findIndex((s) => s.id === stage.id) : -1;
    },
    mainCy(): number {
      // Pipeline axis = vertical center of the middle entry box.
      return this.entryY(1) + ENTRY_H / 2;
    },
    mainY(): number {
      return this.mainCy - STAGE_H / 2;
    },
    entryNodes(): EntryNode[] {
      return PROCESS_ENTRY_SOURCES.map((e, i) => {
        const x = LEFT_PAD;
        const y = this.entryY(i);
        return {
          ...e,
          x,
          y,
          w: ENTRY_W,
          h: ENTRY_H,
          cx: x + ENTRY_W / 2,
          cy: y + ENTRY_H / 2,
        };
      });
    },
    stageNodes(): StageNode[] {
      return PROCESS_STAGES.map((s, i) => {
        const x = this.stageX(i);
        const y = this.mainY;
        return {
          ...s,
          enabled: isStageEnabled(s, this.processModules),
          x,
          y,
          w: STAGE_W,
          h: STAGE_H,
          cx: x + STAGE_W / 2,
          cy: this.mainCy,
        };
      });
    },
    barX(): number {
      return this.stageX(0);
    },
    barW(): number {
      return this.stageX(PROCESS_STAGES.length - 1) + STAGE_W - this.barX;
    },
    barY(): number {
      return this.mainY + STAGE_H + STORE_GAP;
    },
    svgWidth(): number {
      return this.stageX(PROCESS_STAGES.length - 1) + STAGE_W + RIGHT_PAD;
    },
    H(): number {
      return this.barY + STORE_H + TOP_PAD;
    },
    viewBox(): string {
      return `0 0 ${this.svgWidth} ${this.H}`;
    },
    docPos(): { x: number; y: number } {
      if (this.activeStep === 0) {
        const idx = PROCESS_ENTRY_SOURCES.findIndex(
          (e) => e.id === this.entrySource.id,
        );
        return { x: LEFT_PAD + ENTRY_W / 2, y: this.entryY(idx) + ENTRY_H / 2 };
      }
      return {
        x: this.stageX(this.docFullIndex) + STAGE_W / 2,
        y: this.mainCy,
      };
    },
    docTransform(): string {
      return `translate(${this.docPos.x}px, ${this.docPos.y}px)`;
    },
  },
  watch: {
    processModules() {
      // Deactivating a module mid-loop can shorten the path — clamp so
      // activeStep always indexes the current activeStages.
      if (this.activeStep >= this.stepCount) this.activeStep = 0;
    },
  },
  mounted() {
    this.start();
  },
  beforeUnmount() {
    this.stop();
  },
  methods: {
    entryY(i: number): number {
      return TOP_PAD + i * (ENTRY_H + ENTRY_GAP);
    },
    stageX(i: number): number {
      return LEFT_PAD + ENTRY_W + CONVERGE_GAP + i * (STAGE_W + STAGE_GAP);
    },
    entryPath(i: number): string {
      // Right-angle connector from an entry box onto the pipeline axis. The
      // three lines share the final bus segment into the first stage.
      const startX = LEFT_PAD + ENTRY_W;
      const startY = this.entryY(i) + ENTRY_H / 2;
      const busX = this.stageX(0) - 40;
      const endX = this.stageX(0);
      if (Math.abs(startY - this.mainCy) < 1) {
        return `M${startX},${startY} H${endX}`;
      }
      return `M${startX},${startY} H${busX} V${this.mainCy} H${endX}`;
    },
    stagePath(i: number): string {
      return `M${this.stageX(i) + STAGE_W},${this.mainCy} H${this.stageX(i + 1)}`;
    },
    isStageActive(id: string): boolean {
      return this.currentStage?.id === id;
    },
    isEntryActive(id: string): boolean {
      return this.activeStep === 0 && this.entrySource.id === id;
    },
    // Edge i connects full stages i → i+1. The edge just travelled (into the
    // doc's stage) marches blue; everything fully behind the doc is green.
    isEdgeActive(i: number): boolean {
      return i + 1 === this.docFullIndex;
    },
    isEdgeDone(i: number): boolean {
      return i + 1 < this.docFullIndex;
    },
    isEntryEdgeActive(id: string): boolean {
      return this.docFullIndex === 0 && this.entrySource.id === id;
    },
    isEntryEdgeDone(id: string): boolean {
      return this.docFullIndex > 0 && this.entrySource.id === id;
    },
    togglePlay(): void {
      this.playing = !this.playing;
    },
    start(): void {
      this.stop();
      this.timer = setInterval(() => {
        if (!this.playing) return;
        const next = (this.activeStep + 1) % this.stepCount;
        if (next === 0) this.loopCount += 1; // wrap → next entry source
        this.activeStep = next;
      }, STEP_MS);
    },
    stop(): void {
      if (this.timer) {
        clearInterval(this.timer);
        this.timer = null;
      }
    },
  },
});
</script>

