<template>
  <div class="infra" data-test="infrastructure-diagram">
    <!-- Banners + toolbar -->
    <div class="infra-banners">
      <div
        v-if="hasError"
        class="infra-banner infra-banner--error"
        data-test="infra-banner-error"
      >
        <Icon icon="mdi:shield-alert-outline" class="size-4" />
        <span>{{ $t('infra_banner_wrong_region') }} {{ orgRegionLabel }}</span>
      </div>
      <div
        v-else-if="allAligned"
        class="infra-banner infra-banner--ok"
        data-test="infra-banner-ok"
      >
        <Icon icon="mdi:check-circle-outline" class="size-4" />
        <span>{{ $t('infra_banner_all_aligned') }} ({{ orgRegionLabel }})</span>
      </div>
      <div
        v-if="hasAdvisory"
        class="infra-banner infra-banner--advisory"
        data-test="infra-banner-advisory"
      >
        <Icon icon="mdi:information-outline" class="size-4" />
        <span>{{ $t('infra_banner_cross_region') }}: {{ advisoryLabel }}</span>
      </div>
    </div>

    <div class="infra-toolbar">
      <q-btn-toggle
        :model-value="mode"
        @update:model-value="setMode"
        no-caps
        dense
        unelevated
        toggle-color="primary"
        data-test="infra-mode-toggle"
        :options="[
          { label: $t('infra_view_architecture'), value: 'architecture' },
          { label: $t('infra_view_process'), value: 'process' },
        ]"
      />
      <span class="infra-spacer"></span>
      <span
        class="infra-live"
        :class="{ 'is-live': streamStatus === 'live' }"
        data-test="infra-live-indicator"
      >● {{ streamStatus }}</span>
    </div>

    <!-- Process mode: dedicated document-journey pipeline (own component,
         own timer — mount/unmount via v-if handles cleanup). -->
    <ProcessFlowDiagram
      v-if="mode === 'process'"
      :process-modules="processModules"
      data-test="process-flow-host"
      @activate-module="$emit('activate-module', $event)"
    />

    <!-- Architecture diagram -->
    <div v-else class="infra-canvas" data-test="infra-canvas">
      <svg
        :viewBox="viewBox"
        :width="svgWidth"
        :height="H"
        class="infra-svg"
        preserveAspectRatio="xMinYMin meet"
      >
        <defs>
          <marker
            id="infra-arrow"
            markerWidth="9"
            markerHeight="9"
            refX="7"
            refY="3"
            orient="auto"
            markerUnits="strokeWidth"
          >
            <path d="M0,0 L7,3 L0,6 Z" class="infra-arrow-head" />
          </marker>
        </defs>

        <!-- Lane labels -->
        <text
          v-for="(g, gi) in groups"
          :key="'lbl-' + g.id"
          :x="8"
          :y="laneY(Number(gi)) + 14"
          class="infra-lane-label"
        >{{ g.label }}</text>

        <!-- Orthogonal connectors for the document flow -->
        <path
          v-for="(edge, i) in flowPaths"
          :key="'edge-' + i"
          :d="edge.d"
          class="infra-link"
          fill="none"
          marker-end="url(#infra-arrow)"
          :data-test="'infra-edge-' + edge.from + '-' + edge.to"
        />

        <!-- Component cards (draw.io boxes) -->
        <foreignObject
          v-for="node in nodes"
          :key="node.key"
          :x="node.x"
          :y="node.y"
          :width="node.w"
          :height="node.h"
        >
          <div
            class="infra-box"
            :title="node.host || ''"
            :data-test="'infra-node-' + node.key"
          >
            <div class="infra-box-head">
              <Icon :icon="nodeIcon(node)" class="infra-box-icon" />
              <span class="infra-box-label">{{ node.label }}</span>
            </div>
            <div class="infra-box-foot">
              <RegionPill
                :region="node.region"
                :matches="node.matches"
                :severity="node.severity"
              />
              <span
                v-if="node.critical && node.health"
                class="infra-health"
                :class="node.health.status === 'up' ? 'infra-health--up' : 'infra-health--down'"
                :data-test="'infra-health-' + node.key"
              >●<span v-if="node.health.latency_ms != null" class="infra-health-ms">{{ node.health.latency_ms }}ms</span></span>
            </div>
            <!-- Optional-module activation: shows whether the customer has the
                 module switched on, with a shortcut to the Module settings. -->
            <div
              v-if="isModuleNode(node.key)"
              class="infra-box-module"
              :data-test="'infra-module-' + node.key"
            >
              <span
                class="infra-module-status"
                :class="isModuleEnabled(node.key) ? 'infra-module-status--on' : 'infra-module-status--off'"
                :data-test="'infra-module-status-' + node.key"
              >{{ isModuleEnabled(node.key) ? $t('active') : $t('inactive') }}</span>
              <button
                v-if="!isModuleEnabled(node.key)"
                type="button"
                class="infra-module-activate"
                :data-test="'infra-module-activate-' + node.key"
                @click="$emit('activate-module', node.key)"
              >{{ $t('activate') }}</button>
            </div>
          </div>
        </foreignObject>
      </svg>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import { Icon } from '@iconify/vue';
import RegionPill from './RegionPill.vue';
import ProcessFlowDiagram from './ProcessFlowDiagram.vue';
import type {
  InfraComponent,
  InfraKind,
  InfrastructureTopology,
} from './infrastructure-topology.types';

interface LayoutNode extends InfraComponent {
  x: number;
  y: number;
  w: number;
  h: number;
  cx: number;
  cy: number;
}

interface FlowPath {
  from: string;
  to: string;
  label: string;
  d: string;
}

const LANE_H = 138;
const BOX_W = 188;
const BOX_GAP = 60; // horizontal space between boxes so the flow arrows are visible
const BOX_H = 96;
const TOP_PAD = 26;
const LEFT_PAD = 150;
const RIGHT_PAD = 40;
const STEP_X = BOX_W + BOX_GAP; // x-distance between box origins in a lane

const KIND_ICONS: Record<InfraKind, string> = {
  cdn: 'mdi:cloud-outline',
  gateway: 'mdi:gate',
  api: 'mdi:api',
  worker: 'mdi:cog-sync',
  service: 'mdi:cube-outline',
  database: 'mdi:database',
  cache: 'mdi:memory',
  search: 'mdi:magnify',
  analytics: 'mdi:chart-bar',
  object_storage: 'mdi:folder-network',
  stream: 'mdi:transit-connection-variant',
  auth: 'mdi:shield-account',
};

// Real brand logos per component key (bundled offline via src/icons/tech-logos.json,
// registered in boot/iconify.ts). Recognisable at a glance; falls back to the
// generic kind icon for components without a brand logo (e.g. clickhouse, celery).
const KEY_LOGOS: Record<string, string> = {
  postgres: 'logos:postgresql',
  redis: 'logos:redis',
  opensearch: 'logos:opensearch',
  fulltext: 'logos:opensearch',
  spaces: 'logos:digital-ocean',
  kinesis: 'logos:aws',
  kong: 'logos:kong',
  api: 'logos:fastapi',
};

export default defineComponent({
  name: 'InfrastructureDiagram',
  components: { Icon, RegionPill, ProcessFlowDiagram },
  props: {
    topology: {
      type: Object as PropType<InfrastructureTopology | null>,
      default: null,
    },
    streamStatus: { type: String, default: 'offline' },
    // Optional modules the customer can switch on/off. Maps a component key to
    // its activation state (true = activated). Only keys present here are
    // rendered with an activated/deactivated badge + an "Activate" button; a
    // missing key means the component is not an optional module (always-on).
    moduleStatus: {
      type: Object as PropType<Record<string, boolean>>,
      default: () => ({}),
    },
    // Optional-module activation for the process pipeline (pomatch/autoacc),
    // passed through to ProcessFlowDiagram. Missing key = unknown = enabled.
    processModules: {
      type: Object as PropType<Record<string, boolean>>,
      default: () => ({}),
    },
  },
  emits: ['activate-module'],
  data() {
    return {
      mode: 'architecture' as 'architecture' | 'process',
    };
  },
  computed: {
    groups() {
      return this.topology?.groups ?? [];
    },
    H(): number {
      return TOP_PAD * 2 + Math.max(1, this.groups.length) * LANE_H;
    },
    maxLaneCount(): number {
      return Math.max(
        1,
        ...this.groups.map((g) => (Array.isArray(g.components) ? g.components.length : 0)),
      );
    },
    svgWidth(): number {
      // Fixed box size + gap, sized to the busiest lane. N boxes span
      // (N-1) gaps between their origins plus one final box width — no trailing
      // gap after the last box. The canvas scrolls horizontally so boxes always
      // have real spacing (and the flow arrows between them stay visible)
      // instead of being squashed to fit.
      return LEFT_PAD + (this.maxLaneCount - 1) * STEP_X + BOX_W + RIGHT_PAD;
    },
    viewBox(): string {
      return `0 0 ${this.svgWidth} ${this.H}`;
    },
    nodes(): LayoutNode[] {
      const out: LayoutNode[] = [];
      this.groups.forEach((g, gi) => {
        const components = Array.isArray(g.components) ? g.components : [];
        components.forEach((c, ci) => {
          const x = LEFT_PAD + ci * STEP_X;
          const y = this.laneY(gi) + (LANE_H - BOX_H) / 2;
          out.push({ ...c, x, y, w: BOX_W, h: BOX_H, cx: x + BOX_W / 2, cy: y + BOX_H / 2 });
        });
      });
      return out;
    },
    nodeMap(): Record<string, LayoutNode> {
      const m: Record<string, LayoutNode> = {};
      this.nodes.forEach((n) => {
        m[n.key] = n;
      });
      return m;
    },
    flowPaths(): FlowPath[] {
      const edges = this.topology?.flow ?? [];
      const paths: FlowPath[] = [];
      edges.forEach((e) => {
        const a = this.nodeMap[e.from];
        const b = this.nodeMap[e.to];
        if (!a || !b) return;
        paths.push({ from: e.from, to: e.to, label: e.label, d: this.orthogonalPath(a, b) });
      });
      return paths;
    },
    allAligned(): boolean {
      // Green "all aligned" only when: there ARE components, the backend says
      // all_match, AND there is no advisory (amber) — otherwise the green and
      // amber banners would contradict each other.
      return (
        this.nodes.length > 0 &&
        (this.topology?.all_match ?? false) &&
        !this.hasAdvisory
      );
    },
    hasError(): boolean {
      return (
        this.topology?.all_match === false &&
        this.groups.some((g) => (g.components ?? []).some((c) => c.severity === 'error'))
      );
    },
    hasAdvisory(): boolean {
      return this.groups.some((g) => (g.components ?? []).some((c) => c.severity === 'advisory'));
    },
    orgRegionLabel(): string {
      return (this.topology?.org_region ?? '').toUpperCase();
    },
    advisoryLabel(): string {
      const advisory = this.groups
        .flatMap((g) => g.components ?? [])
        .filter((c) => c.severity === 'advisory')
        .map((c) => `${c.label} (${(c.region ?? '').toUpperCase()})`);
      return advisory.join(', ');
    },
  },
  methods: {
    kindIcon(kind: InfraKind): string {
      return KIND_ICONS[kind] || 'mdi:cube-outline';
    },
    nodeIcon(node: { key: string; kind: InfraKind }): string {
      return KEY_LOGOS[node.key] || this.kindIcon(node.kind);
    },
    laneY(index: number): number {
      return TOP_PAD + index * LANE_H;
    },
    orthogonalPath(a: LayoutNode, b: LayoutNode): string {
      // draw.io-style right-angle connector between two box centres.
      if (Math.abs(a.cy - b.cy) < 1) {
        return `M${a.cx + a.w / 2},${a.cy} H${b.cx - b.w / 2}`;
      }
      const startX = a.cx;
      const startY = a.cy + (b.cy > a.cy ? a.h / 2 : -a.h / 2);
      const endX = b.cx;
      const endY = b.cy + (b.cy > a.cy ? -b.h / 2 : b.h / 2);
      const midY = (startY + endY) / 2;
      return `M${startX},${startY} V${midY} H${endX} V${endY}`;
    },
    isModuleNode(key: string): boolean {
      // A component is an optional module iff the parent provided its status.
      return Object.prototype.hasOwnProperty.call(this.moduleStatus, key);
    },
    isModuleEnabled(key: string): boolean {
      return this.moduleStatus[key] === true;
    },
    setMode(mode: 'architecture' | 'process'): void {
      this.mode = mode;
    },
  },
});
</script>

