import AbstractApiService from 'src/services/abstractApiService';
import { DOC2API_URL } from 'pages/APIs';
import type { InfrastructureTopology } from 'src/components/Infrastructure/infrastructure-topology.types';

/**
 * One periodic (Celery Beat) task as returned by
 * doc2-api GET /celery_log/celery_beat_status. Keys mirror the backend's
 * Title-Case field names verbatim. `Last Run Time` is an ISO timestamp or the
 * literal "Never"; `Status` is "On Schedule" | "Delayed" | "Unknown".
 */
export interface BeatTaskStatus {
  'Task Name': string;
  'Last Run Time': string;
  'Next Run Time': string;
  'Status': string;
  'Schedule': string;
}

/**
 * One document-processing task type (OCR, barcode, extraction, PO match …) for
 * the current org, as returned by GET /celery_log/processing_task_status.
 * `service` is the technical Celery task name (e.g. 'celery.ocr.pdf_searchable');
 * `last_run` is an ISO timestamp or null ("never run").
 */
export interface ProcessingTaskStatus {
  service: string;
  last_run: string | null;
  pending: number;
  errors_recent: number;
  completed_recent: number;
}

/**
 * Fetches the live infrastructure topology for the current org from doc2-api.
 *
 * Backend source of truth:
 *   doc2-api/routers/infrastructure/router.py → GET /infrastructure/topology
 *
 * Returns region + region-correctness for every component and a live health
 * probe for the critical datastores (Postgres, OpenSearch, Redis). The endpoint
 * always returns 200 (partial data on a probe failure), so callers only need to
 * handle transport/auth errors.
 */
export default class InfrastructureApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  public async getTopology(): Promise<InfrastructureTopology> {
    return super.get<unknown, InfrastructureTopology>(
      `${DOC2API_URL}/infrastructure/topology`,
    );
  }

  /**
   * Last-run status of every periodic Celery Beat task on the instance.
   *
   * Backend source of truth:
   *   doc2-api/routers/celery_tasks_manager/task_manager.py
   *     → GET /celery_log/celery_beat_status
   */
  public async getBeatStatus(): Promise<BeatTaskStatus[]> {
    return super.get<unknown, BeatTaskStatus[]>(
      `${DOC2API_URL}/celery_log/celery_beat_status`,
    );
  }

  /**
   * Last-run + recent health of the org's document-processing task types
   * (OCR, barcode, extraction, PO match …).
   *
   * Backend source of truth:
   *   doc2-api/routers/celery_tasks_manager/task_manager.py
   *     → GET /celery_log/processing_task_status (org-scoped)
   */
  public async getProcessingStatus(): Promise<ProcessingTaskStatus[]> {
    return super.get<unknown, ProcessingTaskStatus[]>(
      `${DOC2API_URL}/celery_log/processing_task_status`,
    );
  }
}
