<template>
  <div class="proc-tasks" data-test="processing-tasks">
    <div class="bt-toolbar">
      <span class="bt-hint" data-test="processing-tasks-hint">
        {{ $t('infra_proc_hint') }}
      </span>
      <q-btn
        outline
        dense
        no-caps
        color="primary"
        icon="mdi-refresh"
        :label="$t('infra_tasks_refresh')"
        :loading="loading"
        data-test="processing-tasks-refresh"
        @click="load"
      />
    </div>

    <div
      v-if="loading"
      class="flex flex-center q-pa-xl"
      data-test="processing-tasks-loading"
    >
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <q-banner
      v-else-if="error"
      class="bg-red-1 text-red-9"
      data-test="processing-tasks-error"
    >
      {{ $t('infra_tasks_load_failed') }}
      <template #action>
        <q-btn
          flat
          :label="$t('retry')"
          data-test="processing-tasks-retry"
          @click="load"
        />
      </template>
    </q-banner>

    <DocBitsTable
      v-else
      :rows="rows"
      :columns="cols"
      row-key="service"
      table-id="processing_tasks_table"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: false,
        pagination: false,
        columnReorder: false,
      }"
      no-data-label="no_record_found"
      flat-style
      data-test="processing-tasks-table"
    >
      <template #body-cell-name="{ row }">
        <span :data-test="'processing-name-' + row.service">{{ row.name }}</span>
      </template>

      <template #body-cell-last_run="{ row }">
        <span
          v-if="!row.last_run"
          class="bt-never"
          :data-test="'processing-lastrun-' + row.service"
        >
          {{ $t('infra_task_never_run') }}
        </span>
        <span v-else :data-test="'processing-lastrun-' + row.service">
          {{ relativeTime(row.last_run) }}
          <q-tooltip>{{ absoluteTime(row.last_run) }}</q-tooltip>
        </span>
      </template>

      <template #body-cell-status="{ row }">
        <div class="proc-status" :data-test="'processing-status-' + row.service">
          <q-badge
            v-for="badge in badgesFor(row)"
            :key="badge.state"
            :color="badge.color"
            text-color="white"
            rounded
            :label="badgeLabel(badge)"
            :data-test="'processing-status-' + badge.state + '-' + row.service"
          />
        </div>
      </template>
    </DocBitsTable>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { format, parseISO } from 'date-fns';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';
import InfrastructureApiService from 'src/services/infrastructure/InfrastructureApiService';
import type { ProcessingTaskStatus } from 'src/services/infrastructure/InfrastructureApiService';
import { useFormattedTimeAgo } from 'src/boot/timeago';
import logger from 'src/utils/logger';
import {
  labelForService,
  processingBadges,
  type ProcessingBadge,
} from './task-status-helpers';

interface ProcRow {
  service: string;
  name: string;
  last_run: string | null;
  pending: number;
  errors_recent: number;
  completed_recent: number;
}

export default defineComponent({
  name: 'ProcessingTasksStatus',
  components: { DocBitsTable },
  data() {
    return {
      rows: [] as ProcRow[],
      loading: true,
      error: false,
      api: new InfrastructureApiService(),
    };
  },
  computed: {
    cols(): UnifiedTableColumn[] {
      // sorting is disabled (features.sorting:false) — short list, simple
      // snapshot — so `field` is only used for value lookup, never for sort.
      return [
        { name: 'name', label: this.$t('infra_proc_step_col'), align: 'left', field: 'name' },
        { name: 'last_run', label: this.$t('infra_task_last_run_col'), align: 'left', field: 'last_run' },
        { name: 'status', label: this.$t('infra_task_status_col'), align: 'left', field: 'service' },
      ];
    },
  },
  mounted() {
    this.load();
  },
  methods: {
    relativeTime(value: string): string {
      return useFormattedTimeAgo(value);
    },
    absoluteTime(value: string): string {
      try {
        return format(parseISO(value), 'dd.MM.yyyy HH:mm:ss');
      } catch {
        return value;
      }
    },
    badgesFor(row: ProcRow): ProcessingBadge[] {
      return processingBadges(row);
    },
    badgeLabel(badge: ProcessingBadge): string {
      // Count shown as (N) — language-neutral, dodges pluralisation.
      if (badge.state === 'error') {
        return this.$t('infra_proc_status_error') + ' (' + badge.count + ')';
      }
      if (badge.state === 'active') {
        return this.$t('infra_proc_status_active') + ' (' + badge.count + ')';
      }
      return this.$t('infra_proc_status_ok');
    },
    async load() {
      this.loading = true;
      this.error = false;
      try {
        const tasks: ProcessingTaskStatus[] = await this.api.getProcessingStatus();
        this.rows = (Array.isArray(tasks) ? tasks : []).map((t) => ({
          service: t.service,
          name: labelForService(t.service),
          last_run: t.last_run,
          pending: t.pending ?? 0,
          errors_recent: t.errors_recent ?? 0,
          completed_recent: t.completed_recent ?? 0,
        }));
      } catch (err) {
        this.error = true;
        logger.warn('[ProcessingTasks] processing status load failed', err);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>

