// Static definition of the document-processing pipeline shown in the
// "Play process" view on /settings/infrastructure. The journey is the same for
// every customer (frontend-defined, Tolgee-translated) — only the optional
// modules (PO Matching, Auto Accounting) vary per org and are grayed out +
// skipped by the animation when deactivated.
//
// Deliberately import-free so it never pulls the heavy src/constants barrel
// (and its i18n boot chain) into the settings chunk.

export interface ProcessEntrySource {
  id: string;
  icon: string;
  labelKey: string;
  captionKey: string;
}

export interface ProcessStage {
  id: string;
  icon: string;
  labelKey: string;
  captionKey: string;
  /** Key into the processModules prop; present only for optional modules. */
  moduleKey?: 'pomatch' | 'autoacc';
}

export interface ProcessDatastore {
  id: string;
  icon: string;
  labelKey: string;
}

