/**
 * A stage is enabled unless its module is KNOWN to be off. A missing key means
 * "status unknown" (settings still loading) and counts as enabled, mirroring
 * the moduleStatus race guard on the Infrastructure page — the pipeline must
 * never flash a deactivated stage before the async preference fetch resolves.
 */
export function isStageEnabled(
  stage: ProcessStage,
  processModules: Record<string, boolean>,
): boolean {
  return !stage.moduleKey || processModules[stage.moduleKey] !== false;
}
